// Generated by GitHub Copilot - Oct-23-2026
import { useCallback, useEffect, useMemo, useState } from 'react';
import Stepper from '../../components/Stepper';
import JellyBean from '../../components/JellyBean';
import { FLAVORS } from '../../data';
import type { Stock } from '../../services/ai';
import { getActiveStock, onAdminChange } from '../../services/tenant';
import type { Flavor, Mood, Recipe } from '../../types';
import Hero from './Hero';
import Selector from './Selector';
import Mixing from './Mixing';
import Recipes from './Recipes';
import RecipeCard from './RecipeCard';

type Phase = 'hero' | 'flavors' | 'mood' | 'mixing' | 'recipes' | 'card';

const STEP_FOR_PHASE: Record<Phase, number> = { hero: 0, flavors: 0, mood: 0, mixing: 1, recipes: 2, card: 3 };

const FLOATING = [
  { c: '#f08a6a', l: 6, t: 18, s: 40, r: 20 },
  { c: '#e86a7a', l: 12, t: 60, s: 30, r: -30 },
  { c: '#f39a7e', l: 88, t: 30, s: 52, r: 40 },
  { c: '#e46f8c', l: 92, t: 70, s: 34, r: -10 },
  { c: '#f2a07b', l: 80, t: 12, s: 28, r: 70 },
];

/** Partner mark shown on every screen, matching the original JAIME kiosk. */
function PartnerMark() {
  return (
    <p className="partner-mark">
      accenture <span aria-hidden="true">|</span> aws
    </p>
  );
}

/** JAIME iPad experience: hero → flavors → mood → mixing → recipes → recipe card + dispense. */
export default function Demo() {
  const [phase, setPhase] = useState<Phase>('hero');
  const [flavors, setFlavors] = useState<Flavor[]>([]);
  const [mood, setMood] = useState<Mood | null>(null);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [selected, setSelected] = useState<Recipe | null>(null);
  const [stock, setStock] = useState<Stock>({});
  const [dispenserId, setDispenserId] = useState<string | null>(null);

  const available = useMemo(() => FLAVORS.filter((f) => (stock[f.id] ?? 0) > 0), [stock]);

  const refreshStock = useCallback(() => {
    getActiveStock().then((s) => {
      setStock(s.stock);
      setDispenserId(s.dispenserId);
      // Drop picks that were just unloaded from the trays.
      setFlavors((prev) => prev.filter((f) => (s.stock[f.id] ?? 0) > 0));
    });
  }, []);

  // Live-update the flavor list when trays are edited in the admin (same or another tab).
  useEffect(() => {
    refreshStock();
    return onAdminChange(refreshStock);
  }, [refreshStock]);

  const reset = (to: Phase) => {
    setFlavors([]);
    setMood(null);
    setRecipes([]);
    setSelected(null);
    setPhase(to);
    if (to === 'flavors') refreshStock();
  };

  const toggleFlavor = (f: Flavor) =>
    setFlavors((prev) =>
      prev.some((p) => p.id === f.id) ? prev.filter((p) => p.id !== f.id) : prev.length < 2 ? [...prev, f] : prev,
    );

  if (phase === 'hero') {
    return (
      <div className="page page--sunny">
        <Hero onStart={() => reset('flavors')} />
        <PartnerMark />
      </div>
    );
  }

  const cream = phase === 'mixing' || phase === 'recipes' || phase === 'card';

  return (
    <div className={`page ${cream ? 'page--cream' : 'page--peach'}`}>
      <div className="floating-beans" aria-hidden="true">
        {FLOATING.map((b, i) => (
          <span key={i} style={{ left: `${b.l}%`, top: `${b.t}%`, animationDelay: `${i * 0.7}s` }}>
            <JellyBean color={b.c} size={b.s} rotate={b.r} />
          </span>
        ))}
      </div>

      <div className="demo-topbar">
        <Stepper current={STEP_FOR_PHASE[phase]} />
        <button type="button" className="btn btn--restart" onClick={() => reset('flavors')}>
          <span aria-hidden="true">↻</span> Restart
        </button>
      </div>

      <main id="main" className="demo-main">
        {(phase === 'flavors' || phase === 'mood') && (
          <Selector
            mode={phase}
            available={available}
            flavors={flavors}
            mood={mood}
            onToggleFlavor={toggleFlavor}
            onSelectMood={setMood}
            onBack={() => setPhase(phase === 'mood' ? 'flavors' : 'hero')}
            onNext={() => setPhase(phase === 'flavors' ? 'mood' : 'mixing')}
          />
        )}
        {phase === 'mixing' && mood && flavors.length === 2 && (
          <Mixing
            flavor1={flavors[0]}
            flavor2={flavors[1]}
            mood={mood}
            stock={stock}
            onDone={(r) => {
              setRecipes(r);
              setPhase('recipes');
            }}
          />
        )}
        {phase === 'recipes' && mood && (
          <Recipes
            recipes={recipes}
            flavors={flavors}
            mood={mood}
            onBack={() => setPhase('mood')}
            onSelect={(r) => {
              setSelected(r);
              setPhase('card');
            }}
          />
        )}
        {phase === 'card' && mood && selected && (
          <RecipeCard
            recipe={selected}
            mood={mood}
            dispenserId={dispenserId}
            onBack={() => setPhase('recipes')}
            onRestart={() => reset('hero')}
          />
        )}
      </main>
      <PartnerMark />
    </div>
  );
}
